Image::Image(std::unique_ptr<const Concept> pimpl) noexcept
	: service::Object{ getTypeNames(), getResolvers() }
	, _pimpl { std::move(pimpl) }
{
}

service::TypeNames Image::getTypeNames() const noexcept
{
	return {
		R"gql(Image)gql"sv
	};
}

service::ResolverMap Image::getResolvers() const noexcept
{
	return {
		{ R"gql(id)gql"sv, [this](service::ResolverParams&& params) { return resolveId(std::move(params)); } },
		{ R"gql(tags)gql"sv, [this](service::ResolverParams&& params) { return resolveTags(std::move(params)); } },
		{ R"gql(width)gql"sv, [this](service::ResolverParams&& params) { return resolveWidth(std::move(params)); } },
		{ R"gql(height)gql"sv, [this](service::ResolverParams&& params) { return resolveHeight(std::move(params)); } },
		{ R"gql(scanAt)gql"sv, [this](service::ResolverParams&& params) { return resolveScanAt(std::move(params)); } },
		{ R"gql(tagIds)gql"sv, [this](service::ResolverParams&& params) { return resolveTagIds(std::move(params)); } },
		{ R"gql(artworks)gql"sv, [this](service::ResolverParams&& params) { return resolveArtworks(std::move(params)); } },
		{ R"gql(tagPaths)gql"sv, [this](service::ResolverParams&& params) { return resolveTagPaths(std::move(params)); } },
		{ R"gql(createdAt)gql"sv, [this](service::ResolverParams&& params) { return resolveCreatedAt(std::move(params)); } },
		{ R"gql(sortScore)gql"sv, [this](service::ResolverParams&& params) { return resolveSortScore(std::move(params)); } },
		{ R"gql(__typename)gql"sv, [this](service::ResolverParams&& params) { return resolve_typename(std::move(params)); } },
		{ R"gql(frameCount)gql"sv, [this](service::ResolverParams&& params) { return resolveFrameCount(std::move(params)); } },
		{ R"gql(publishedAt)gql"sv, [this](service::ResolverParams&& params) { return resolvePublishedAt(std::move(params)); } }
	};
}

void Image::beginSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->beginSelectionSet(params);
}

void Image::endSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->endSelectionSet(params);
}

service::AwaitableResolver Image::resolveId(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getId(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<response::IdType>::convert(std::move(result), std::move(params));
}

