void AddImageDetails(const std::shared_ptr<schema::ObjectType>& typeImage, const std::shared_ptr<schema::Schema>& schema)
{
	typeImage->AddFields({
		schema::Field::Make(R"gql(id)gql"sv, R"md(图片 ID。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(ID)gql"sv))),
		schema::Field::Make(R"gql(width)gql"sv, R"md(图片宽度，未知时为 null。)md"sv, std::nullopt, schema->LookupType(R"gql(Int)gql"sv)),
		schema::Field::Make(R"gql(height)gql"sv, R"md(图片高度，未知时为 null。)md"sv, std::nullopt, schema->LookupType(R"gql(Int)gql"sv)),
		schema::Field::Make(R"gql(frameCount)gql"sv, R"md(动画帧数，未知时为 null。)md"sv, std::nullopt, schema->LookupType(R"gql(Int)gql"sv)),
		schema::Field::Make(R"gql(createdAt)gql"sv, R"md(入库时间。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(String)gql"sv))),
		schema::Field::Make(R"gql(scanAt)gql"sv, R"md(上次扫描时间，从未扫描时为 null。)md"sv, std::nullopt, schema->LookupType(R"gql(String)gql"sv)),
		schema::Field::Make(R"gql(publishedAt)gql"sv, R"md(所属作品发布时间中的最大值；没有作品或都没填时为 null。)md"sv, std::nullopt, schema->LookupType(R"gql(String)gql"sv)),
		schema::Field::Make(R"gql(tagIds)gql"sv, R"md(标签 ID 列表。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->WrapType(introspection::TypeKind::LIST, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(ID)gql"sv))))),
		schema::Field::Make(R"gql(tags)gql"sv, R"md(标签列表，name 是该标签自身的标准名。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->WrapType(introspection::TypeKind::LIST, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(Tag)gql"sv))))),
		schema::Field::Make(R"gql(tagPaths)gql"sv, R"md(标签路径列表。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->WrapType(introspection::TypeKind::LIST, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(TagPath)gql"sv))))),
		schema::Field::Make(R"gql(artworks)gql"sv, R"md(所属作品，按发布时间倒序；没有作品时为空数组。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->WrapType(introspection::TypeKind::LIST, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(ImageArtwork)gql"sv))))),
		schema::Field::Make(R"gql(sortScore)gql"sv, R"md(文本/参考图相似度分数，仅在 orderBy: SIMILARITY 且提供 sortText 或
referenceImageId 时有值。

图片没有向量时为 null；referenceImageId 模式下结果图片都有向量。)md"sv, std::nullopt, schema->LookupType(R"gql(Float)gql"sv))
	});
}

